import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const Chat = () => {
  const location = useLocation();
  const { personality, name } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');

  // 현재 날짜와 시간을 반환하는 함수 (24시간 기준, 분까지만 표시)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });

    return `${date} ${time}`;
  };

  const getTimeOnly = () => {
    const now = new Date();
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return time;
  };

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    const sentTime = getTimeOnly();
    const newMessage = { sender: "user", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);

    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality, name }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: `${name}: ${chatbotMessage}`, time: receivedTime },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
    }
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div>
      <div><strong>{currentDateTime}</strong></div>
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender}>
            <strong>{chat.sender === "user" ? "User" : name}</strong>: {chat.message}
            <div><em>{chat.time}</em></div>
          </div>
        ))}
      </div>
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}
        />
        <button onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
